export interface DelegatedSubagentLiveState {
	status?: string;
	currentTool?: string;
	currentToolArgs?: string;
	recentOutput: string[];
	recentTools: Array<{ tool: string; args: string }>;
	model?: string;
	toolCount: number;
	durationMs: number;
	tokens: number;
	taskProgress: DelegatedSubagentTaskProgress[];
	startedAt: number;
	updatedAt: number;
}

const delegatedLiveState = new Map<string, DelegatedSubagentLiveState>();

export function updateDelegatedLiveState(requestId: string, update: Partial<DelegatedSubagentLiveState>): void {
	const now = Date.now();
	const existing = delegatedLiveState.get(requestId) ?? {
		recentOutput: [],
		recentTools: [],
		toolCount: 0,
		durationMs: 0,
		tokens: 0,
		taskProgress: [],
		startedAt: now,
		updatedAt: now,
	};
	const next: DelegatedSubagentLiveState = {
		...existing,
		...update,
		recentOutput: update.recentOutput ?? existing.recentOutput,
		recentTools: update.recentTools ?? existing.recentTools,
		model: update.model ?? existing.model,
		toolCount: update.toolCount ?? existing.toolCount,
		durationMs: update.durationMs ?? (now - existing.startedAt),
		tokens: update.tokens ?? existing.tokens,
		taskProgress: update.taskProgress ?? existing.taskProgress,
		startedAt: existing.startedAt,
		updatedAt: now,
	};
	delegatedLiveState.set(requestId, next);
}

export function appendDelegatedLiveOutput(requestId: string, line?: string): void {
	if (!line || !line.trim() || line.trim() === "(running...)") return;
	const fallbackNow = Date.now();
	const existing = delegatedLiveState.get(requestId) ?? {
		recentOutput: [],
		recentTools: [],
		toolCount: 0,
		durationMs: 0,
		tokens: 0,
		taskProgress: [],
		startedAt: fallbackNow,
		updatedAt: fallbackNow,
	};
	const recentOutput = [...existing.recentOutput, line];
	delegatedLiveState.set(requestId, {
		...existing,
		recentOutput,
		updatedAt: Date.now(),
	});
}

export function getDelegatedLiveState(requestId: string): DelegatedSubagentLiveState | undefined {
	const state = delegatedLiveState.get(requestId);
	return state ? structuredClone(state) : undefined;
}

export function clearDelegatedLiveState(requestId: string): void {
	delegatedLiveState.delete(requestId);
}

import type { MessageRenderOptions, Theme } from "@earendil-works/pi-coding-agent";
import { Box, Container, Spacer, Text } from "@earendil-works/pi-tui";

interface AssistantContent {
	type: string;
	text?: string;
	name?: string;
	id?: string;
	arguments?: Record<string, unknown>;
}

interface SessionMessage {
	role: string;
	content?: AssistantContent[] | string;
	usage?: { input?: number; output?: number; cacheRead?: number; cacheWrite?: number; cost?: { total?: number } };
	model?: string;
}

interface DelegatedDetails {
	requestId?: string;
	agent?: string;
	task?: string;
	context?: "fresh" | "fork";
	model?: string;
	messages?: SessionMessage[];
	parallelResults?: Array<{
		agent?: string;
		messages?: SessionMessage[];
		isError?: boolean;
		errorText?: string;
	}>;
}

const DEFAULT_AGENT = "delegate";
const PREVIEW_LINES = 8;

function extractTextContent(content: unknown): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return "";
	const lines: string[] = [];
	for (const part of content) {
		if (!part || typeof part !== "object") continue;
		if ((part as { type?: string }).type !== "text") continue;
		const text = (part as { text?: unknown }).text;
		if (typeof text === "string") lines.push(text);
	}
	return lines.join("\n");
}

function formatToolCall(name: string, args: Record<string, unknown>): string {
	switch (name) {
		case "bash": {
			const cmd = String(args.command ?? "").replace(/[\n\t]/g, " ").trim();
			return `$ ${cmd.length > 80 ? cmd.slice(0, 80) + "..." : cmd}`;
		}
		case "read": return `[read: ${args.path ?? args.file_path ?? ""}]`;
		case "write": return `[write: ${args.path ?? args.file_path ?? ""}]`;
		case "edit": return `[edit: ${args.path ?? args.file_path ?? ""}]`;
		case "grep": return `[grep: /${args.pattern ?? ""}/ in ${args.path ?? "."}]`;
		case "find": return `[find: ${args.pattern ?? ""} in ${args.path ?? "."}]`;
		case "ls": return `[ls: ${args.path ?? "."}]`;
		default: {
			const a = JSON.stringify(args).slice(0, 50);
			return `[${name}: ${a}${JSON.stringify(args).length > 50 ? "..." : ""}]`;
		}
	}
}

function extractToolCalls(messages: SessionMessage[]): string[] {
	const calls: string[] = [];
	for (const msg of messages) {
		if (msg.role !== "assistant" || !Array.isArray(msg.content)) continue;
		for (const block of msg.content) {
			if (block.type === "toolCall" && block.name) {
				calls.push(formatToolCall(block.name, block.arguments ?? {}));
			}
		}
	}
	return calls;
}

function extractAssistantText(messages: SessionMessage[]): string {
	for (let i = messages.length - 1; i >= 0; i--) {
		const msg = messages[i];
		if (msg.role !== "assistant") continue;
		const text = extractTextContent(msg.content);
		if (text.trim()) return text;
	}
	return "";
}

function extractUsage(messages: SessionMessage[]): { input: number; output: number; cacheRead: number; cacheWrite: number; cost: number; model?: string; turns: number } {
	let input = 0, output = 0, cacheRead = 0, cacheWrite = 0, cost = 0, turns = 0;
	let model: string | undefined;
	for (const msg of messages) {
		if (msg.role !== "assistant") continue;
		turns++;
		if (msg.usage) {
			input += msg.usage.input ?? 0;
			output += msg.usage.output ?? 0;
			cacheRead += msg.usage.cacheRead ?? 0;
			cacheWrite += msg.usage.cacheWrite ?? 0;
			cost += msg.usage.cost?.total ?? 0;
		}
		if (msg.model) model = msg.model;
	}
	return { input, output, cacheRead, cacheWrite, cost, model, turns };
}

function formatTokensShort(n: number): string {
	if (n >= 1000) return `${Math.round(n / 1000)}k`;
	return String(n);
}

function addPreviewText(box: Box, text: string, options: MessageRenderOptions, theme: Theme): void {
	const lines = text.split("\n");
	if (options.expanded || lines.length <= PREVIEW_LINES) {
		box.addChild(new Text(theme.fg("toolOutput", text), 0, 0));
		return;
	}
	box.addChild(new Text(theme.fg("toolOutput", lines.slice(0, PREVIEW_LINES).join("\n")), 0, 0));
	box.addChild(new Text(theme.fg("warning", `\n... (${lines.length - PREVIEW_LINES} more lines — Ctrl+O to expand)`), 0, 0));
}

export function renderDelegatedSubagentResult(
	message: { content?: unknown; details?: DelegatedDetails },
	options: MessageRenderOptions,
	theme: Theme,
) {
	const details = message.details;
	const parallelResults = details?.parallelResults ?? [];
	const hasParallelResults = parallelResults.length > 0;
	const agent = hasParallelResults ? "parallel" : (details?.agent ?? DEFAULT_AGENT);
	const context = details?.context === "fork" ? theme.fg("warning", " [fork]") : "";
	const messages = hasParallelResults
		? parallelResults.flatMap((result) => (result.messages ?? []) as SessionMessage[])
		: ((details?.messages ?? []) as SessionMessage[]);
	const text = extractTextContent(message.content);

	const usage = extractUsage(messages);
	const toolCalls = extractToolCalls(messages);
	const toolCount = toolCalls.length;
	const tokensLabel = `${formatTokensShort(usage.output)} tok`;

	const container = new Container();
	container.addChild(new Spacer(1));
	const box = new Box(1, 1, (text: string) => theme.bg("toolSuccessBg", text));

	const icon = theme.fg("success", "ok");
	const stats = hasParallelResults
		? `${parallelResults.length} task${parallelResults.length === 1 ? "" : "s"}, ${toolCount} tool${toolCount === 1 ? "" : "s"}, ${tokensLabel}`
		: `${toolCount} tool${toolCount === 1 ? "" : "s"}, ${tokensLabel}`;
	box.addChild(new Text(`${icon} ${theme.fg("toolTitle", theme.bold(agent))}${context} | ${stats}`, 0, 0));
	box.addChild(new Spacer(1));

	if (details?.task) {
		const taskPreview = details.task.length > 120 ? `${details.task.slice(0, 120)}...` : details.task;
		box.addChild(new Text(theme.fg("dim", `Task: ${taskPreview}`), 0, 0));
		box.addChild(new Spacer(1));
	}

	if (hasParallelResults) {
		for (let index = 0; index < parallelResults.length; index++) {
			const result = parallelResults[index]!;
			const taskLabel = result.agent || `task-${index + 1}`;
			box.addChild(new Text(theme.fg("toolTitle", `=== Task ${index + 1}: ${taskLabel} ===`), 0, 0));
			const taskMessages = (result.messages ?? []) as SessionMessage[];
			const taskText = extractAssistantText(taskMessages);
			if (result.isError) {
				const errorText = result.errorText || "Task failed.";
				box.addChild(new Text(theme.fg("error", errorText), 0, 0));
				box.addChild(new Spacer(1));
				continue;
			}

			if (!taskText) {
				box.addChild(new Text(theme.fg("dim", "(no assistant text)"), 0, 0));
				box.addChild(new Spacer(1));
				continue;
			}

			addPreviewText(box, taskText, options, theme);
			box.addChild(new Spacer(1));
		}
	} else {
		if (toolCalls.length > 0) {
			const showCalls = options.expanded ? toolCalls : toolCalls.slice(0, 5);
			for (const call of showCalls) {
				box.addChild(new Text(theme.fg("dim", call), 0, 0));
			}
			if (!options.expanded && toolCalls.length > 5) {
				box.addChild(new Text(theme.fg("warning", `... (${toolCalls.length - 5} more tool calls)`), 0, 0));
			}
			box.addChild(new Spacer(1));
		}

		if (text) {
			addPreviewText(box, text, options, theme);
			box.addChild(new Spacer(1));
		}
	}

	const statsLine = `${usage.turns} turn${usage.turns === 1 ? "" : "s"} in:${usage.input} out:${usage.output} R${formatTokensShort(usage.cacheRead)} W${formatTokensShort(usage.cacheWrite)}${usage.cost ? ` $${usage.cost.toFixed(4)}` : ""} ${usage.model ?? details?.model ?? ""}`;
	box.addChild(new Text(theme.fg("dim", statsLine), 0, 0));

	container.addChild(box);
	return container;
}

import type { Model } from "@earendil-works/pi-ai";
import type { ResolvedModelRef } from "./template-conditionals.ts";

const PREFERRED_PROVIDERS = ["openai-codex", "anthropic", "github-copilot", "openrouter"];

export interface SelectedModelCandidate {
	model: Model<any>;
	alreadyActive: boolean;
}

export interface RegistryLike {
	find(provider: string, modelId: string): Model<any> | undefined;
	getAll(): Model<any>[];
	getAvailable(): Model<any>[];
	isUsingOAuth(model: Model<any>): boolean;
	hasConfiguredAuth?: (model: Model<any>) => boolean;
	getApiKeyAndHeaders?: (model: Model<any>) => Promise<{
		ok: boolean;
		apiKey?: string;
		headers?: Record<string, string>;
		error?: string;
	}>;
}

export interface ScopedModelLike {
	model: Model<any>;
}

export interface ModelSelectionOptions {
	scopedModels?: readonly ScopedModelLike[];
}

export function isSameModel(a: Model<any> | undefined, b: Model<any> | undefined): boolean {
	if (!a || !b) return a === b;
	return a.provider === b.provider && a.id === b.id;
}

function modelSpecMatches(modelSpec: string, model: Model<any>): boolean {
	const slashIndex = modelSpec.indexOf("/");
	if (slashIndex !== -1) {
		const provider = modelSpec.slice(0, slashIndex);
		const modelId = modelSpec.slice(slashIndex + 1);
		return provider === model.provider && modelId === model.id;
	}

	return modelSpec === model.id;
}

function orderMatchesByProviderPreference(models: Model<any>[]): Model<any>[] {
	const prioritized: Model<any>[] = [];
	const seen = new Set<string>();

	for (const provider of PREFERRED_PROVIDERS) {
		for (const model of models) {
			const key = `${model.provider}/${model.id}`;
			if (model.provider === provider && !seen.has(key)) {
				prioritized.push(model);
				seen.add(key);
			}
		}
	}

	for (const model of models) {
		const key = `${model.provider}/${model.id}`;
		if (!seen.has(key)) {
			prioritized.push(model);
			seen.add(key);
		}
	}

	return prioritized;
}

function getScopedModels(options?: ModelSelectionOptions): Model<any>[] | undefined {
	const scopedModels = options?.scopedModels?.map((entry) => entry.model) ?? [];
	return scopedModels.length > 0 ? scopedModels : undefined;
}

function isInScope(model: Model<any>, scopedModels: Model<any>[] | undefined): boolean {
	return !scopedModels || scopedModels.some((candidate) => isSameModel(candidate, model));
}

function getModelCandidates(
	modelSpec: string,
	registry: Pick<RegistryLike, "find" | "getAll">,
	scopedModels: Model<any>[] | undefined,
): Model<any>[] {
	const slashIndex = modelSpec.indexOf("/");

	if (slashIndex !== -1) {
		const provider = modelSpec.slice(0, slashIndex);
		const modelId = modelSpec.slice(slashIndex + 1);
		if (!provider || !modelId) return [];
		if (modelId.split("/").some((segment) => segment.length === 0)) return [];
		const model = registry.find(provider, modelId);
		return model && isInScope(model, scopedModels) ? [model] : [];
	}

	const sourceModels = scopedModels ?? registry.getAll();
	const allMatches = sourceModels.filter((model) => model.id === modelSpec);
	if (allMatches.length <= 1) return allMatches;
	return orderMatchesByProviderPreference(allMatches);
}

async function hasUsableAuth(model: Model<any>, registry: RegistryLike, scopedModels: Model<any>[] | undefined): Promise<boolean> {
	if (isInScope(model, scopedModels) && scopedModels) return true;
	const availableMatch = registry.getAvailable().some((candidate) => isSameModel(candidate, model));
	if (availableMatch) return true;
	if (!registry.isUsingOAuth(model)) return false;
	if (registry.hasConfiguredAuth) return registry.hasConfiguredAuth(model);
	if (registry.getApiKeyAndHeaders) {
		const auth = await registry.getApiKeyAndHeaders(model);
		return auth.ok;
	}
	return false;
}

export async function selectModelCandidate(
	modelSpecs: string[],
	currentModel: Model<any> | undefined,
	registry: RegistryLike,
	options?: ModelSelectionOptions,
): Promise<SelectedModelCandidate | undefined> {
	const scopedModels = getScopedModels(options);
	if (currentModel && isInScope(currentModel, scopedModels) && modelSpecs.some((spec) => modelSpecMatches(spec, currentModel))) {
		return { model: currentModel, alreadyActive: true };
	}

	for (const spec of modelSpecs) {
		for (const model of getModelCandidates(spec, registry, scopedModels)) {
			if (await hasUsableAuth(model, registry, scopedModels)) {
				return { model, alreadyActive: false };
			}
		}
	}

	return undefined;
}

export function getResolvedModelRef(model: Model<any>): ResolvedModelRef {
	return { provider: model.provider, id: model.id };
}

import type { Theme } from "@earendil-works/pi-coding-agent";
import { Box, Container, Spacer, Text } from "@earendil-works/pi-tui";
import {
	getDelegatedLiveState,
	type DelegatedSubagentLiveState,
	type DelegatedSubagentTask,
	type DelegatedSubagentTaskProgress,
} from "./subagent-runtime.ts";

export const DELEGATED_WIDGET_KEY = "prompt-subagent-progress";

function formatDuration(ms: number): string {
	const seconds = Math.floor(ms / 1000);
	if (seconds < 60) return `${seconds}s`;
	const minutes = Math.floor(seconds / 60);
	const remaining = seconds % 60;
	return `${minutes}m${remaining}s`;
}

function formatTokens(n: number | undefined): string {
	if (!n) return "0";
	if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
	return String(n);
}

function normalizeModelLabel(model: string | undefined): string | undefined {
	if (!model) return undefined;
	return model.includes("/") ? model.split("/").pop() : model;
}

function formatToolCall(tool: string, args: string): string {
	const safeArgs = args ?? "";
	switch (tool) {
		case "bash": {
			const cmd = safeArgs.replace(/[\n\t]/g, " ").trim();
			return `$ ${cmd.length > 80 ? cmd.slice(0, 80) + "..." : cmd}`;
		}
		case "read": return `[read: ${safeArgs}]`;
		case "write": return `[write: ${safeArgs}]`;
		case "edit": return `[edit: ${safeArgs}]`;
		default: {
			const short = safeArgs.length > 60 ? safeArgs.slice(0, 60) + "..." : safeArgs;
			return `[${tool}: ${short}]`;
		}
	}
}

function stateKey(state: DelegatedSubagentLiveState | undefined, elapsed: number): string {
	if (!state) return "none";
	const elapsedBucket = Math.floor(elapsed / 1000);
	const tool = state.currentTool ?? "";
	const outputLen = state.recentOutput.length;
	const outputTail = state.recentOutput.length > 0
		? state.recentOutput[state.recentOutput.length - 1]?.slice(0, 80) ?? ""
		: "";
	const toolsLen = state.recentTools.length;
	const taskProgressKey = state.taskProgress
		.map((entry) => {
			const recentOutputLines = (entry.recentOutputLines ?? []).slice(-3).join("\u241f");
			const recentTool = entry.recentTools?.[entry.recentTools.length - 1];
			return [
				entry.index ?? "",
				entry.agent,
				entry.status ?? "",
				entry.currentTool ?? "",
				entry.toolCount ?? 0,
				entry.tokens ?? 0,
				entry.model ?? "",
				recentTool?.tool ?? "",
				recentTool?.args ?? "",
				recentOutputLines,
			].join(":");
		})
		.join("|");
	return `${state.status}|${tool}|${state.toolCount}|${state.tokens}|${outputLen}:${outputTail}|${toolsLen}|${state.model ?? ""}|${taskProgressKey}|${elapsedBucket}`;
}

function getParallelPreviewLimits(taskCount: number): { tools: number; output: number } {
	if (taskCount <= 2) return { tools: 3, output: 6 };
	if (taskCount <= 4) return { tools: 2, output: 4 };
	return { tools: 2, output: 3 };
}

function resolveTaskProgress(
	taskProgress: DelegatedSubagentTaskProgress[],
	task: DelegatedSubagentTask,
	index: number,
): DelegatedSubagentTaskProgress | undefined {
	return taskProgress.find((entry) => entry.index === index)
		?? taskProgress.find((entry) => entry.index === undefined && entry.agent === task.agent)
		?? taskProgress[index];
}

function getTaskOutputLines(progress: DelegatedSubagentTaskProgress | undefined): string[] {
	if (!progress) return [];
	if (progress.recentOutputLines && progress.recentOutputLines.length > 0) {
		return progress.recentOutputLines.filter((line) => line.trim());
	}
	if (!progress.recentOutput?.trim()) return [];
	return progress.recentOutput.split("\n").filter((line) => line.trim());
}

function getTaskHeader(
	index: number,
	task: DelegatedSubagentTask,
	progress: DelegatedSubagentTaskProgress | undefined,
	theme: Theme,
): string {
	const status = progress?.status ?? "pending";
	const modelLabel = normalizeModelLabel(progress?.model ?? task.model);
	const modelSuffix = modelLabel ? ` ${theme.fg("dim", modelLabel)}` : "";
	const label = `task ${index + 1} · ${task.agent}`;
	if (status === "running") return `${theme.fg("toolTitle", label)}${modelSuffix} ${theme.fg("warning", "running")}`;
	if (status === "completed") return `${theme.fg("toolTitle", label)}${modelSuffix} ${theme.fg("success", "completed")}`;
	if (status === "failed") return `${theme.fg("toolTitle", label)}${modelSuffix} ${theme.fg("error", "failed")}`;
	return `${theme.fg("toolTitle", label)}${modelSuffix} ${theme.fg("dim", status)}`;
}

function addParallelTaskPreview(
	box: Box,
	task: DelegatedSubagentTask,
	progress: DelegatedSubagentTaskProgress | undefined,
	index: number,
	taskCount: number,
	theme: Theme,
): void {
	box.addChild(new Text(getTaskHeader(index, task, progress, theme), 0, 0));

	const limits = getParallelPreviewLimits(taskCount);
	if (!progress) {
		box.addChild(new Text(theme.fg("dim", "    waiting for updates"), 0, 0));
		return;
	}

	if (progress.currentTool) {
		box.addChild(new Text(theme.fg("warning", `    > ${formatToolCall(progress.currentTool, progress.currentToolArgs ?? "")}`), 0, 0));
	}

	const recentTools = (progress.recentTools ?? []).slice(-limits.tools);
	for (const tool of recentTools) {
		box.addChild(new Text(theme.fg("dim", `    ${formatToolCall(tool.tool, tool.args)}`), 0, 0));
	}

	const outputLines = getTaskOutputLines(progress);
	const visibleOutputLines = outputLines.slice(-limits.output);
	for (const line of visibleOutputLines) {
		box.addChild(new Text(theme.fg("dim", `    ${line}`), 0, 0));
	}

	const hiddenLineCount = outputLines.length - visibleOutputLines.length;
	if (hiddenLineCount > 0) {
		box.addChild(new Text(theme.fg("warning", `    ... (${hiddenLineCount} older line${hiddenLineCount === 1 ? "" : "s"})`), 0, 0));
	}

	if (!progress.currentTool && recentTools.length === 0 && visibleOutputLines.length === 0) {
		if (progress.status === "completed") {
			const toolCount = progress.toolCount ?? 0;
			box.addChild(new Text(theme.fg("dim", `    completed (${toolCount} tool${toolCount === 1 ? "" : "s"})`), 0, 0));
		} else if (progress.status === "failed") {
			box.addChild(new Text(theme.fg("error", "    task failed"), 0, 0));
		} else {
			box.addChild(new Text(theme.fg("dim", "    waiting for output"), 0, 0));
		}
	}
}

function rebuildBox(
	box: Box,
	agent: string,
	contextSuffix: string,
	taskPreview: string,
	parallelTasks: DelegatedSubagentTask[],
	isParallel: boolean,
	state: DelegatedSubagentLiveState | undefined,
	elapsed: number,
	theme: Theme,
	requestModel?: string,
): void {
	box.clear();

	const taskProgress = state?.taskProgress ?? [];
	const baseToolCount = state?.toolCount ?? 0;
	const baseTokens = state?.tokens ?? 0;
	const parallelToolCount = taskProgress.reduce((sum, entry) => sum + (entry.toolCount ?? 0), 0);
	const parallelTokens = taskProgress.reduce((sum, entry) => sum + (entry.tokens ?? 0), 0);
	const toolCount = isParallel && parallelToolCount > 0 ? parallelToolCount : baseToolCount;
	const tokens = isParallel && parallelTokens > 0 ? parallelTokens : baseTokens;
	const tokensLabel = formatTokens(tokens);
	const duration = formatDuration(elapsed);
	const isThinking = toolCount === 0 && tokens === 0;
	const icon = theme.fg("warning", "...");
	const modelLabel = isParallel
		? requestModel
		: normalizeModelLabel(state?.model ?? requestModel);
	const modelSuffix = modelLabel ? ` ${theme.fg("dim", modelLabel)}` : "";
	const stats = isThinking
		? `thinking, ${duration}`
		: `${toolCount} tool${toolCount === 1 ? "" : "s"}, ${tokensLabel} tok, ${duration}`;

	if (isParallel) {
		const completedCount = taskProgress.filter((entry) => entry.status === "completed").length;
		const runningLabel = `parallel ${completedCount}/${parallelTasks.length} running`;
		box.addChild(new Text(`${icon} ${theme.fg("toolTitle", theme.bold(runningLabel))}${contextSuffix}${modelSuffix} | ${stats}`, 0, 0));
	} else {
		box.addChild(new Text(
			`${icon} ${theme.fg("toolTitle", theme.bold(agent))}${contextSuffix}${modelSuffix} | ${stats}`,
			0,
			0,
		));
	}
	box.addChild(new Spacer(1));

	if (!isParallel) {
		box.addChild(new Text(theme.fg("dim", `Task: ${taskPreview}`), 0, 0));
		box.addChild(new Spacer(1));
	}

	if (isParallel) {
		for (let index = 0; index < parallelTasks.length; index++) {
			const task = parallelTasks[index]!;
			const progress = resolveTaskProgress(taskProgress, task, index);
			addParallelTaskPreview(box, task, progress, index, parallelTasks.length, theme);
			if (index < parallelTasks.length - 1) {
				box.addChild(new Spacer(1));
			}
		}
		return;
	}

	const recentTools = state?.recentTools ?? [];
	for (const tool of recentTools) {
		box.addChild(new Text(theme.fg("dim", formatToolCall(tool.tool, tool.args)), 0, 0));
	}
	if (state?.currentTool) {
		const active = formatToolCall(state.currentTool, state.currentToolArgs ?? "");
		box.addChild(new Text(theme.fg("warning", `> ${active}`), 0, 0));
	}

	if (state && state.recentOutput.length > 0) {
		if (recentTools.length > 0 || state.currentTool) {
			box.addChild(new Spacer(1));
		}
		for (const line of state.recentOutput) {
			box.addChild(new Text(theme.fg("dim", `  ${line}`), 0, 0));
		}
	}
}

export function createDelegatedProgressWidget(
	requestId: string,
	agent: string,
	context: "fresh" | "fork",
	task: string,
	tasks: DelegatedSubagentTask[] | undefined,
	theme: Theme,
	model?: string,
): Container & { dispose?(): void } {
	const contextSuffix = context === "fork" ? theme.fg("warning", " [fork]") : "";
	const taskPreview = task.length > 200 ? `${task.slice(0, 200)}...` : task;
	const parallelTasks = tasks ?? [];
	const isParallel = parallelTasks.length > 0;
	const parallelModels = [...new Set(parallelTasks
		.map((task) => normalizeModelLabel(task.model))
		.filter((entry): entry is string => !!entry))];
	const requestModel = isParallel
		? (parallelModels.length === 1 ? parallelModels[0] : undefined)
		: normalizeModelLabel(model);

	const container = new Container();
	container.addChild(new Spacer(1));
	const box = new Box(1, 1, (text: string) => theme.bg("toolPendingBg", text));
	container.addChild(box);

	let lastKey = "";

	container.render = (width: number): string[] => {
		const state = getDelegatedLiveState(requestId);
		const elapsed = state ? Date.now() - state.startedAt : 0;
		const key = stateKey(state, elapsed);
		if (key !== lastKey) {
			lastKey = key;
			rebuildBox(box, agent, contextSuffix, taskPreview, parallelTasks, isParallel, state, elapsed, theme, requestModel);
		}
		return Container.prototype.render.call(container, width);
	};

	return container;
}

